mapper.select:
select id, house_id, cage_id, mother_id, father_id, birth_batch_id, birth_cycle_id, type, gender, breed, arrival_method, arrival_date, weight, state_version, is_active, is_quarantined, quarantine_time, quarantine_reason, request_id, departure_date, departure_reason, create_by, create_time, update_by, update_time from rabbits where house_id = #{houseId}
and id in #{id}
and 1 = 0 order by id for update

select id, house_id, cage_id, mother_id, father_id, birth_batch_id, birth_cycle_id, type, gender, breed, arrival_method, arrival_date, weight, state_version, is_active, is_quarantined, quarantine_time, quarantine_reason, request_id, departure_date, departure_reason, create_by, create_time, update_by, update_time from rabbits where house_id = #{houseId} and request_id in
#{requestId}
order by request_id

select id, house_id, cage_id, mother_id, father_id, birth_batch_id, birth_cycle_id, type, gender, breed, arrival_method, arrival_date, weight, state_version, is_active,
       is_quarantined, quarantine_time, quarantine_reason,
       request_id,
       departure_date, departure_reason, create_by, create_time, update_by, update_time
from rabbits
where house_id = #{houseId}

    and cage_id = #{cageId}


    and type = #{type}


    and is_active = #{active}

order by id desc

select id, house_id, cage_id, mother_id, father_id, birth_batch_id, birth_cycle_id, type, gender, breed, arrival_method, arrival_date, weight, state_version, is_active,
       is_quarantined, quarantine_time, quarantine_reason,
       request_id,
       departure_date, departure_reason, create_by, create_time, update_by, update_time
from rabbits
where house_id = #{houseId}

    and cage_id = #{cageId}


    and type = #{type}


    and is_active = #{active}

order by id desc
limit #{limit} offset #{offset}

select id as id, cage_id as cageId
from rabbits
where house_id = #{houseId}

    and id in

        #{id}



    and 1 = 0
